/**
 * One full card from the model, for the add sheet's Fill with AI and the
 * word screen's Improve with AI.
 */
import { ai as aiApi } from '@/api/endpoints.js';
import type { WordDraft } from '@/db/mutations.js';
import { aiJobFromApi } from '@/sync/mapping.js';
import { watchJob } from './poll.js';
import { noteRefusal } from './quota.js';

/**
 * Asks the model for the card of one entry and waits for it (see
 * `watchJob` for how often it looks). Throws when the job fails, comes back
 * without a card or takes too long, with the server's reason when it gave
 * one.
 */
export async function generateCard(
  notebookId: string,
  headword: string,
  options: { hint?: string; signal?: AbortSignal } = {},
): Promise<WordDraft> {
  let job;
  try {
    job = aiJobFromApi(await aiApi.createCards(notebookId, [headword], options.hint));
  } catch (cause) {
    await noteRefusal(cause);
    throw cause;
  }
  job = await watchJob(job, options.signal === undefined ? {} : { signal: options.signal });
  const card = job.cards[0];
  if (job.status !== 'done' || card === undefined) throw new Error(job.error ?? 'failed');
  return card;
}
